\encoding UTF8
WITH vp AS (SELECT * FROM question_bank WHERE pipeline_metadata::jsonb ? 'verified_provisional' AND quality_review_status IN ('human_verified','auto_judged_high') AND NOT (pipeline_metadata::jsonb ? 'demoted_at') AND NOT (pipeline_metadata::jsonb ? 'ai_extras' AND (pipeline_metadata::jsonb->'ai_extras') ? 'topic_match_quality' AND ((pipeline_metadata::jsonb->'ai_extras')->>'topic_match_quality')='fallback') AND (pipeline_metadata::jsonb ? 'match_tier' AND (pipeline_metadata::jsonb->>'match_tier') IN ('tier1_page_inline','tier1b_position_page_inline')) AND id NOT IN (SELECT id FROM gate2c_demoted))
SELECT 'figure_ref_in_text' AS k, count(*) FILTER (WHERE question_text ~* '(şekil|grafik|tablo|yukarıdaki|aşağıdaki|görsel|grafikte|şemada|deneyde)') AS n, count(*) AS total FROM vp;
